test('owner answers the gate while a delta check is pending', () => {
  const s = capped();
  const ans = r.ap(['answer', '--out', s.out, '--gate-rev', '2', '--reply', 'rec', '--rec-hash', recHashOf(s.out), '--by', 'human']);
  expect(ans.status).toBe(0);
  expect(JSON.parse(fs.readFileSync(path.join(s.out, 'spend.json'), 'utf8')).reserved.map((x: any) => x.attempt)).not.toContain(s.check.attempt);
  expect(r.ap(['check', '--out', s.out, '--attempt', s.check.attempt, '--unavailable', 'x']).status).toBe(3);
  expect(decisions(s.out).find(d => d.gate_rev === 2 && d.label === 'P1').carried_gate_from).toBeUndefined();
});

test('check refuses a wrong attempt, a stale receipt and an unknown family without carrying', () => {
  const s = capped();
  result(s.check.result, 'f'.repeat(64), []);
  expect(r.ap(['check','--out',s.out,'--attempt','x','--result',s.check.result,'--model','openai/gpt-6.1-sol']).stderr).toContain('ATTEMPT_MISMATCH');
  expect(r.ap(['check','--out',s.out,'--attempt',s.check.attempt,'--result',s.check.result,'--model','openai/gpt-6.1-sol']).stderr).toContain('RESULT_RECEIPT_MISSING');
  expect(readRunJson(s.out).carry.verdict).toBe('check_pending');
});

